import dev.tactical.tacz.DistantShots;import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;import java.lang.reflect.*;
public class FarChecks{static int count;static void ok(boolean b,String s){count++;if(!b)throw new AssertionError(s);}public static void main(String[]a)throws Exception{Method hook=Class.forName("dev.tactical.tacz.mixin.FarShotRangeMixin").getDeclaredMethod("tactical4$range",int.class,String.class,CallbackInfoReturnable.class);hook.setAccessible(true);
 for(String s:new String[]{"shoot","shoot_3p","pzpos;10;64;-10;shoot","pzpos;0;0;0;shoot_3p","silence","silence_3p","pzpos;10;64;-10;silence"})for(int base:new int[]{1,16,128,256,1024}){int expected=s.endsWith("silence")||s.endsWith("silence_3p")?128:768;ok(DistantShots.range(base,s,base*3)==expected,"effective radius "+s);CallbackInfoReturnable<Integer> ci=new CallbackInfoReturnable<>(base*3);hook.invoke(null,base,s,ci);ok(ci.value==expected&&ci.canceled,"actual common mixin callback sets radius");}
 for(String s:new String[]{"reload_empty","dry_fire","melee_push","draw","","pzpos;1;2;3;reload_empty"})ok(DistantShots.range(64,s,192)==192,"other noises unchanged");ok(DistantShots.range(64,null,192)==192,"null untouched");ok(DistantShots.range(0,"shoot",0)==0,"disabled shot audio remains disabled");ok(DistantShots.range(-1,"shoot",0)==0,"invalid range not enabled");
 double near=Math.pow(1-100./768,2),far=Math.pow(1-600./768,2);ok(near>far&&far>0,"native squared distance fade audible until boundary");ok(768*768==589824,"network distance square within int bounds");System.out.println("FAR_SHOT_CHECKS="+count);}}
